  NutritionGoals get goals => const NutritionCalculator().calculate(weight: weight, height: height, age: age, sex: sex, activity: activity);
  static String key(DateTime d) => '${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';
  bool get isToday => key(selectedDay) == key(DateTime.now());
  List<FoodEntry> get dayMeals => meals.where((e) => e.dateKey == key(selectedDay)).toList();
  int get kcal => dayMeals.fold(0, (s,e) => s + e.kcal);
  double get protein => dayMeals.fold(0.0, (s,e) => s + e.protein);
  double get fat => dayMeals.fold(0.0, (s,e) => s + e.fat);
  double get carbs => dayMeals.fold(0.0, (s,e) => s + e.carbs);
