  }
  Future<void> _save() async { await storage.writeDouble('weight',weight); await storage.writeDouble('startWeight',startWeight); await storage.writeDouble('goalWeight',goalWeight); await storage.writeInt('age',age); await storage.writeInt('height',height); await storage.writeInt('water',water); await storage.writeString('sex',sex); await storage.writeList('meals',meals.map((e)=>e.toJson()).toList()); await storage.writeList('weights',weights.map((e)=>e.toJson()).toList()); }
