class FoodEntry { final Food food; final double grams; final String dateKey; const FoodEntry(this.food,this.grams,this.dateKey); factory FoodEntry.fromFood(Food f,double g,String d)=>FoodEntry(f,g,d); int get kcal=>(food.kcal*grams/100).round(); double get protein=>food.protein*grams/100; double get fat=>food.fat*grams/100; double get carbs=>food.carbs*grams/100; double get fiber=>food.fiber*grams/100; FoodEntry copyWith({double? grams})=>FoodEntry(food,grams??this.grams,dateKey); Map<String,dynamic> toJson()=>{'food':food.toJson(),'grams':grams,'dateKey':dateKey}; static FoodEntry? fromJson(Map<String,dynamic> j){final f=j['food'];final g=(j['grams'] as num?)?.toDouble();final d=j['dateKey'] as String?;if(f is! Map||g==null||d==null||g<=0)return null;return FoodEntry(Food.fromJson(Map<String,dynamic>.from(f)),g,d);}}
class WeightEntry { final double weight; final String date; final DateTime dateTime; const WeightEntry(this.weight,this.date,this.dateTime); Map<String,dynamic> toJson()=>{'weight':weight,'date':date,'dateTime':dateTime.toIso8601String()}; static WeightEntry? fromJson(Map<String,dynamic> j){final w=(j['weight'] as num?)?.toDouble();final d=j['date'] as String?;if(w==null||d==null)return null;return WeightEntry(w,d,DateTime.tryParse(j['dateTime'] as String? ?? '')??DateTime.now());}}
class WeightChart extends StatelessWidget { final List<WeightEntry> entries; final double goal; const WeightChart({super.key,required this.entries,required this.goal}); @override Widget build(BuildContext c)=>CustomPaint(painter:_ChartPainter(entries,goal),child:const SizedBox.expand()); }
class _ChartPainter extends CustomPainter { final List<WeightEntry> e; final double goal; const _ChartPainter(this.e,this.goal); @override void paint(Canvas c,Size s){if(e.isEmpty)return;final vals=e.map((x)=>x.weight).toList();final min=( [...vals,goal].reduce((a,b)=>a<b?a:b)-2);final max=( [...vals,goal].reduce((a,b)=>a>b?a:b)+2);final range=(max-min).clamp(1.0,1000.0);final l=42.0,t=12.0,r=s.width-8,b=s.height-25;final grid=Paint()..color=const Color(0xFFE1E6EA);for(int i=0;i<=4;i++){final y=t+(b-t)*i/4;c.drawLine(Offset(l,y),Offset(r,y),grid);}final gy=b-((goal-min)/range)*(b-t);final gp=Paint()..color=_green..strokeWidth=2;c.drawLine(Offset(l,gy),Offset(r,gy),gp);final line=Paint()..color=_blue..strokeWidth=3..style=PaintingStyle.stroke;final dot=Paint()..color=_blue;final p=Path();for(int i=0;i<vals.length;i++){final x=l+(r-l)*(vals.length==1?.5:i/(vals.length-1));final y=b-((vals[i]-min)/range)*(b-t);if(i==0)p.moveTo(x,y);else p.lineTo(x,y);c.drawCircle(Offset(x,y),4,dot);}c.drawPath(p,line);} @override bool shouldRepaint(covariant _ChartPainter old)=>true; }

